def add(n,kind,scans,lines,words,statement,reconstruction,check='agrees',reason='The Codex lead agrees with the passage; it is a lead, not an indexed entry.'):
    files='K29-02_transcription.tex' if max(scans)<=202 else 'K29-03_transcription.tex'
    items.append(dict(id=f'SA12-{n}',sources=[f'codex:{files.replace("_transcription.tex", "")}/{s}' for s in scans],kind=kind,cote=29,scans=scans,lines=files+':'+lines,his_words=words,statement=statement,reconstruction=reconstruction,check=check,check_reason=reason))
